mapper.select:
SELECT id, mission_title, mission_content FROM tbl_mission_pool WHERE category_id = #{categoryId} AND mission_type = 'RELATIVE'
AND id != #{excludedMissionId}
ORDER BY id

SELECT ROUND(AVG(daily.net_amount), 2) AS base_amount,
       (
           SELECT MIN(purchase.amount)
           FROM tbl_transaction purchase
           WHERE purchase.user_id = #{userId}
             AND purchase.category_id = #{categoryId}
             AND purchase.tr_date BETWEEN #{startDate} AND #{endDate}
             AND purchase.classification = 'CONSUMPTION'
             AND purchase.direction = 'OUT'
             AND purchase.is_excluded_from_summary = 0
             AND purchase.is_refund = 0
             AND purchase.amount > 0
       ) AS minimum_purchase_amount
FROM (
    SELECT tr_date,
           SUM(CASE WHEN is_refund = 1 THEN -COALESCE(refunded_amount, amount) ELSE amount END) AS net_amount
    FROM tbl_transaction
    WHERE user_id = #{userId}
      AND category_id = #{categoryId}
      AND tr_date BETWEEN #{startDate} AND #{endDate}
      AND classification = 'CONSUMPTION'
      AND direction = 'OUT'
      AND is_excluded_from_summary = 0
    GROUP BY tr_date
    HAVING net_amount > 0
) daily
